<script setup lang="ts">
import { ref } from 'vue';
import { useRouter } from 'vue-router';
import { useAuthStore } from '@/stores/auth.store';

const router = useRouter();
const authStore = useAuthStore();
const username = ref('');
const password = ref('');

const handleLogin = async () => {
  if (!username.value || !password.value) return;
  const success = await authStore.login(username.value, password.value);
  if (success) router.push('/');
};
</script>

<template>
  <div class="login-page"><div class="login-art"><img src="@/assets/boardgame-hero.webp" alt="LuNu Board Game Club"><div class="art-wash"></div><div class="login-quote"><span>“</span><p>Không chỉ là một ván chơi.<br>Là cách chúng ta kết nối.</p><small>LU NU BOARD GAME CLUB</small></div></div><div class="login-panel"><div class="login-brand"><span class="brand-glyph"><i class="bi bi-diamond-half"></i></span><div><strong>LuNu</strong><small>Board Game Club</small></div></div><div class="login-copy"><div class="eyebrow">Private club · Est. 2026</div><h1>Chơi có gu.<br><span>Thắng có chất.</span></h1><p>Đăng nhập để bước vào những bàn chơi được tuyển chọn cho bạn.</p></div><form @submit.prevent="handleLogin"><label>Tên đăng nhập<div class="input-wrap"><i class="bi bi-person"></i><input v-model="username" type="text" placeholder="your_username" required></div></label><label class="mt-3">Mật khẩu<div class="input-wrap"><i class="bi bi-lock"></i><input v-model="password" type="password" placeholder="••••••••" required></div></label><div v-if="authStore.error" class="login-error"><i class="bi bi-exclamation-circle me-2"></i>{{ authStore.error }}</div><div class="login-options"><label class="remember"><input type="checkbox"> <span>Ghi nhớ thiết bị</span></label><a href="#">Quên mật khẩu?</a></div><button type="submit" class="btn btn-gold w-100 login-submit" :disabled="authStore.loading"><span v-if="authStore.loading" class="spinner-border spinner-border-sm me-2"></span><i v-else class="bi bi-arrow-right me-2"></i>{{ authStore.loading ? 'ĐANG KẾT NỐI...' : 'VÀO CÂU LẠC BỘ' }}</button></form><div class="login-footer login-access-note"><span><i class="bi bi-shield-lock me-2"></i>Quyền truy cập hiện được cấp riêng bởi LuNu Club</span></div><div class="login-legal">Bằng việc tiếp tục, bạn đồng ý với Quy tắc cộng đồng và Chính sách riêng tư của LuNu.</div></div></div>
</template>

